#include <string>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <sstream>

class Solution {
public:
    std::string abbreviateProduct(int left, int right) {
        int cnt2 = 0, cnt5 = 0;
        for (int i = left; i <= right; ++i) {
            int temp = i;
            while (temp % 2 == 0) { cnt2++; temp /= 2; }
            while (temp % 5 == 0) { cnt5++; temp /= 5; }
        }
        int zeros = std::min(cnt2, cnt5);

        double totalLog = 0;
        for (int i = left; i <= right; ++i) {
            totalLog += std::log10(i);
        }
        totalLog -= zeros;

        int rem2 = zeros, rem5 = zeros;
        long long suff = 1;
        bool isLarge = false;

        for (int i = left; i <= right; ++i) {
            int temp = i;
            while (rem2 > 0 && temp % 2 == 0) { rem2--; temp /= 2; }
            while (rem5 > 0 && temp % 5 == 0) { rem5--; temp /= 5; }

            suff *= temp;
            if (suff >= 10000000000LL) {
                isLarge = true;
                suff %= 10000000000LL;
            }
        }

        if (!isLarge && suff < 10000000000LL) {
            return std::to_string(suff) + "e" + std::to_string(zeros);
        }

        double frac = totalLog - std::floor(totalLog);
        int pref = (int)std::pow(10, frac + 4);

        int lastFive = suff % 100000;
        std::ostringstream oss;
        oss << pref << "..." << std::setfill('0') << std::setw(5) << lastFive << "e" << zeros;
        return oss.str();
    }
};

