        int zeros = Math.min(cnt2, cnt5);

        double totalLog = 0;
        for (int i = left; i <= right; i++) {
            totalLog += Math.log10(i);
        }
        totalLog -= zeros;

        int rem2 = zeros, rem5 = zeros;
        long suff = 1;
        boolean isLarge = false;

        for (int i = left; i <= right; i++) {
            int temp = i;
            while (rem2 > 0 && temp % 2 == 0) { rem2--; temp /= 2; }
            while (rem5 > 0 && temp % 5 == 0) { rem5--; temp /= 5; }

            suff *= temp;
            if (suff >= 10000000000L) {
                isLarge = true;
                suff %= 10000000000L;
            }
        }

        if (!isLarge && suff < 10000000000L) {
            return suff + "e" + zeros;
        }

        double frac = totalLog - Math.floor(totalLog);
        int pref = (int) Math.pow(10, frac + 4);
