var abbreviateProduct = function(left, right) {
    let cnt2 = 0, cnt5 = 0;
    for (let i = left; i <= right; i++) {
        let temp = i;
        while (temp % 2 === 0) { cnt2++; temp /= 2; }
        while (temp % 5 === 0) { cnt5++; temp /= 5; }
    }
    const zeros = Math.min(cnt2, cnt5);

    let totalLog = 0;
    for (let i = left; i <= right; i++) {
        totalLog += Math.log10(i);
    }
    totalLog -= zeros;

    let rem2 = zeros, rem5 = zeros;
    let suff = 1n;
    let isLarge = false;

    for (let i = left; i <= right; i++) {
        let temp = i;
        while (rem2 > 0 && temp % 2 === 0) { rem2--; temp /= 2; }
        while (rem5 > 0 && temp % 5 === 0) { rem5--; temp /= 5; }

        suff *= BigInt(temp);
        if (suff >= 10000000000n) {
            isLarge = true;
            suff %= 10000000000n;
        }
    }

    if (!isLarge && suff < 10000000000n) {
        return `${suff}e${zeros}`;
    }

    const frac = totalLog - Math.floor(totalLog);
    const pref = Math.floor(10 ** (frac + 4));
    const lastFive = Number(suff % 100000n).toString().padStart(5, '0');

    return `${pref}...${lastFive}e${zeros}`;
};
